    }
    function fillHidden() {
        var sels = document.querySelectorAll("select"), i;
        for (i = 0; i < sels.length; i++) {
            var s = sels[i];
            if (s.__eqilManaged && s.value === (s.__eqilPh || "") && s.__eqilDef && s.__eqilDef !== s.value && (s.disabled || !shown(s)) && hasValue(s, s.__eqilDef)) { s.value = s.__eqilDef; }
        }
        for (var n in groups) {
            var g = groups[n];
            if (g.managed && g.els && g.def !== null && g.def !== undefined && checkedValue(g.els) === null && !shown(g.els[0])) { setRadio(g.els, g.def); }
        }
    }
    function flag(els) {
        if (!styled) {
            styled = true;
            var st = document.createElement("style");
            st.textContent = ".eqil-missing{outline:2px solid #dc2626 !important;outline-offset:2px}";
            (document.head || document.body).appendChild(st);
        }
        for (var i = 0; i < els.length; i++) { els[i].classList.add("eqil-missing"); }
        try {
            var f = sim();
            if (f && f.uiManager && typeof f.uiManager.showNotification === "function") { f.uiManager.showNotification(TXT[lang()][1], "warning"); }
        } catch (e) {}
    }

    function wrapCheck(orig) {
        return function (d) {
            pass();
